import mongoose from 'mongoose';

export const SWIPE_ACTIONS = Object.freeze(['LIKE', 'NOPE', 'FRIENDZONE']);

const swipeSchema = new mongoose.Schema(
  {
    // Generated by the client (crypto.randomUUID) so the same swipe can be
    // retried or undone idempotently without waiting for a server id.
    clientId: { type: String, required: true, unique: true, match: /^[0-9a-f-]{36}$/i },
    sessionId: { type: String, required: true, index: true, match: /^[0-9a-f-]{36}$/i },
    profileSlug: { type: String, required: true, match: /^[a-z0-9-]+$/ },
    action: { type: String, required: true, enum: SWIPE_ACTIONS },
  },
  { timestamps: true, versionKey: false },
);

// One decision per profile per session.
swipeSchema.index({ sessionId: 1, profileSlug: 1 }, { unique: true });

export const Swipe = mongoose.models.Swipe ?? mongoose.model('Swipe', swipeSchema);